// The NAPLPS renderer's limits the Naplps builder holds its calls to (renderer parity PAR-40),
// generated by scripts/picture-limits.ts from the renderer's files, their one
// home (crates/naplps/src/limits.rs, crates/naplps/src/surface.rs, crates/naplps-render/src/main.rs), at
// the commit scripts/check.sh names (NAPLPS_FROM), which checks this copy against them.
// Each keeps the renderer's name: write a limit by its name, never its
// figure. Do not edit this file; generate it.

/** Bytes one macro definition may hold. */
export const MAX_MACRO_BYTES = 4096;
/** Vertices of one polygon, scribble or arc spline (the standard asks for at least 256). */
export const MAX_VERTICES = 4096;
/**
 * Layers of a page, drawn in this order: 0 the background (the stream's picture), 1 the scene,
 * 2 the sprites, 3 the overlay (ANIM-12).
 */
export const LAYERS = 4;
/** Frames of one object (ANIM-14). */
export const MAX_OBJECT_FRAMES = 16;
/** The width of the picture an object's position, size and rectangle are in (ANIM-11). */
export const OBJECT_PICTURE_WIDTH = 640;
/** The height of the picture an object's position, size and rectangle are in (ANIM-11). */
export const OBJECT_PICTURE_HEIGHT = 480;
/**
 * Bytes of an object's label, UTF-8: the text a screen reader speaks for it (DEC-6638 item 6,
 * row 6.1). The same bound as a sound's label in the engine's OBJECT record (REQ-37), the one
 * other label NeoTeletext carries for a reader.
 */
export const MAX_LABEL_BYTES = 64;
/**
 * The share of the unit screen's height a display shows: 25/32 = 0.78125, the 256 x 200
 * display of ANSI X3.110-1983 Table D1, and what PP3 shows (its 5/128 text rows are exactly 24
 * of its 480 lines: 480 x 32/25 x 5/128 = 24).
 */
export const DISPLAY_HEIGHT_NUMERATOR = 25;
/** See `DISPLAY_HEIGHT_NUMERATOR`. */
export const DISPLAY_HEIGHT_DENOMINATOR = 32;
/** A 16-entry colour map, as PP3's VGA mode. */
export const DEFAULT_PALETTE_BITS = 4;
